\documentclass[11pt]{article}

\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{example}[theorem]{Example}
\newtheorem{conjecture}[theorem]{Conjecture}

\newcommand{\code}[1]{\texttt{#1}}
\newcommand{\Gam}{\Gamma}
\newcommand{\id}{\mathrm{id}}
\newcommand{\Aut}{\mathrm{Aut}}
\newcommand{\aeval}{\mathrm{aeval}}
\newcommand{\NN}{\mathbb{N}}
\newcommand{\QQ}{\mathbb{Q}}

\title{Plethystic Triviality of the Shifted $t$-Schur Basis\\
and the Diagonal Plethysm Group}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We study a one-parameter deformation of the Schur $Q$-functions, the \emph{shifted
$t$-Schur functions} $S^t_\lambda$, defined through the Fourier modes of a $t$-deformed odd
vertex (``GJZ''-type) operator on the ring $\Gam = R[p_1,p_3,p_5,\dots]$ generated by the
odd power sums. We prove that this deformation is \emph{plethystically trivial}: the single
$R$-algebra endomorphism $\varphi_t$ determined by $\varphi_t(p_{2k+1}) = (1-t^{2k+1})\,
p_{2k+1}$ carries the Schur $Q$-basis onto the shifted $t$-Schur basis, i.e.
$S^t_\lambda = \varphi_t(Q_\lambda)$ for every strict partition $\lambda$. Working over
$K = \QQ(t)$, where every factor $1 - t^{2k+1}$ is a unit, we show $\varphi_t$ is an algebra
automorphism with explicit inverse $\psi_t(p_{2k+1}) = (1-t^{2k+1})^{-1} p_{2k+1}$, whence
$Q_\lambda = \psi_t(S^t_\lambda)$ and a family $\{S^t_{\lambda_i}\}$ is $K$-linearly
independent iff $\{Q_{\lambda_i}\}$ is. We then identify the structural mechanism behind
triviality. The maps $\Phi_a : p_{2k+1} \mapsto a_k\, p_{2k+1}$ (the \emph{diagonal
plethysms}) satisfy $\Phi_a \circ \Phi_b = \Phi_{a\cdot b}$ and $\Phi_1 = \id$; the
assignment $a \mapsto \Phi_a$ is injective, and on invertible sequences it is a faithful
group homomorphism $(K^\times)^{\NN} \to \Aut_K(\Gam)$. We establish the sharp dichotomy that
$\Phi_a$ is injective iff $a$ never vanishes, exhibit explicit non-injective degenerations,
and locate $\varphi_t$ at the non-vanishing locus, degenerating under $t \mapsto 1$. All
results were formally verified in Lean~4 with Mathlib.
\end{abstract}

\section{Introduction}

\subsection{Context}
Symmetric function theory hosts several canonical bases indexed by partitions. The Schur
$Q$-functions $Q_\lambda$, indexed by \emph{strict partitions} $\lambda$, form a
distinguished basis of the subalgebra $\Gam \subseteq \Lambda$ generated by the odd power
sums; they govern the projective (spin) representation theory of the symmetric groups, the
cohomology of isotropic Grassmannians, and the theory of $P$- and $Q$-functions. A modern way
to generate them uses \emph{vertex operators}: one realizes $Q_\lambda$ as an ordered product
of creation--annihilation operators applied to the vacuum $1$.

Deforming the vertex-operator data by a parameter $t$ produces \emph{shifted $t$-Schur
functions} $S^t_\lambda$, built by a recursion with $t$-dependent coefficients at every step.
We show that, despite appearances, $S^t_\lambda$ is obtained from $Q_\lambda$ by a single
diagonal plethystic substitution on the generators.

\subsection{Results}
Our contributions: (1) the triviality identity $S^t_\lambda = \varphi_t(Q_\lambda)$
(Theorem~\ref{thm:triv}), driven by an intertwining relation
(Lemma~\ref{lem:inter}); (2) invertibility and basis triviality
(Theorems~\ref{thm:auto}--\ref{thm:basis}); (3) the diagonal plethysm group
(Section~\ref{sec:group}); (4) the non-triviality boundary (Section~\ref{sec:boundary}).
Bracketed names, e.g.\ [\code{Sfun\_eq\_phiT\_Qfun}], cite the formal identifiers.

\section{Setup and definitions}

Fix $K = \QQ(t)$, the field of rational functions in a transcendental $t$.

\begin{definition}[Odd power-sum ring]
Let $\Gam = \mathrm{MvPolynomial}(\NN, K)$, the polynomial $K$-algebra on $X_0,X_1,X_2,\dots$.
We interpret $X_k$ as $p_{2k+1}$, so $\Gam$ models $K[p_1,p_3,p_5,\dots]$. [\code{Lam}]
\end{definition}

\begin{definition}[Deformation scalars]
Let $t = X \in \QQ(t)$ and $c_k = 1 - t^{2k+1}$ for $k \in \NN$. [\code{cc}]
\end{definition}

\begin{lemma}[Non-vanishing]\label{lem:ccne}
For every $k$, $c_k \neq 0$. [\code{cc\_ne}]
\end{lemma}
\begin{proof}
Write $1 - t^{2k+1} = \iota(1 - X^{2k+1})$ for the fraction-field embedding
$\iota:\QQ[X]\hookrightarrow\QQ(X)$. Since $\iota$ is injective and $1 - X^{2k+1}\neq0$
(value $1$ at $X=0$), the claim follows.
\end{proof}

\begin{definition}[Inverse scalars]
$d_k = 1/c_k = (1 - t^{2k+1})^{-1}$ [\code{dd}]; by Lemma~\ref{lem:ccne} this is well defined
and $c_k d_k = 1$ [\code{cc\_mul\_dd}].
\end{definition}

\begin{definition}[Plethystic operators]
Let $\varphi_t,\psi_t:\Gam\to\Gam$ be the $K$-algebra homomorphisms with
\[
\varphi_t(X_k) = c_k X_k = (1-t^{2k+1})X_k, \qquad
\psi_t(X_k) = d_k X_k = \frac{X_k}{1-t^{2k+1}}.
\]
[\code{phiT}, \code{psiT}] Concretely $\varphi_t = \aeval(k\mapsto C(c_k)X_k)$; in plethystic
notation $\varphi_t$ performs $p_n \mapsto (1-t^n)p_n$ on the odd generators.
\end{definition}

\section{The vertex-operator construction}

\begin{definition}[Creation functions]
For $\mathrm{cf}:\NN\to\Gam$ define $q^{\mathrm{cf}}_0 = 1$ and
\[
q^{\mathrm{cf}}_{m+1} = \frac{1}{m+1}\sum_{k=0}^{\lfloor m/2\rfloor}
2\,\mathrm{cf}_k\, q^{\mathrm{cf}}_{m-2k}.
\]
[\code{qGen}] These are the homogeneous coefficients of $\exp(\sum_k \tfrac{2}{2k+1}
\mathrm{cf}_k z^{2k+1})$. Set $q_m = q^{(X_k)}_m$ [\code{q}] and $q^t_m = q^{(c_kX_k)}_m$
[\code{qt}].
\end{definition}

\begin{lemma}[Creation functions intertwine]\label{lem:qt}
$q^t_m = \varphi_t(q_m)$ for all $m$. [\code{qt\_eq\_phiT\_q}]
\end{lemma}
\begin{proof}
Strong induction on $m$. Base cases $m=0,1$ are immediate. For the step, $\varphi_t$ is an
algebra map and commutes with the sum/products in the recursion; applying it to $q_m$ replaces
each $X_k$ by $c_kX_k$, yielding exactly the recursion for $q^t_m$.
\end{proof}

\begin{definition}[Annihilation and vertex components]
For $d:\NN\to K$ define $A_d:\Gam\to\Gam[u]$ by $A_d(X_k)=X_k - d_k u^{2k+1}$ [\code{annGen}].
Set $A=A_{(4)}$ [\code{annShift}], $A^t=A_{(4/c_k)}$ [\code{annShiftT}]. For $P=\sum_m P_m u^m$
write $T_{\mathrm{qf},n}(P)=\sum_m \mathrm{qf}_{n+m}P_m$ [\code{Tsum}]. Then
\[
B_n(f) = T_{q,n}(A(f)), \qquad B^t_n(f) = T_{q^t,n}(A^t(f)).
\]
[\code{B}, \code{Bt}]
\end{definition}

\begin{lemma}[Intertwining relation]\label{lem:inter}
For all $n$ and $f$: $B^t_n(\varphi_t(f)) = \varphi_t(B_n(f))$. [\code{Bt\_phiT}]
\end{lemma}
\begin{proof}
First, $A^t\circ\varphi_t = (\varphi_t)_*\circ A$ [\code{annShiftT\_phiT}]: $\varphi_t$ scales
$X_k$ by $c_k$ while the deformed annihilation uses $4/c_k$, and the scalings cancel on
$u^{2k+1}$. Second, $T_{q^t,n}((\varphi_t)_*P) = \varphi_t(T_{q,n}(P))$ [\code{Tsum\_map\_phiT}]
by Lemma~\ref{lem:qt} and linearity. Compose.
\end{proof}

\begin{definition}[The symmetric functions]
For parts $\lambda=(\lambda_1,\dots,\lambda_\ell)$,
\[
Q_\lambda = (B_{\lambda_1}\circ\cdots\circ B_{\lambda_\ell})(1), \qquad
S^t_\lambda = (B^t_{\lambda_1}\circ\cdots\circ B^t_{\lambda_\ell})(1),
\]
[\code{Qfun}, \code{Sfun}] as right folds. A \emph{strict partition} is a strictly decreasing
list of positive integers [\code{IsStrictPartition}].
\end{definition}

\section{Plethystic triviality}

\begin{theorem}[Triviality identity]\label{thm:triv}
For every list of parts $\lambda$ (in particular every strict partition),
$S^t_\lambda = \varphi_t(Q_\lambda)$.
[\code{Sfun\_eq\_phiT\_Qfun}, \code{shifted\_tSchur\_eq\_phiT\_Q}]
\end{theorem}
\begin{proof}
Induction on $\lambda$. Empty: both sides are $\varphi_t(1)=1$. For $\lambda=(a)::\mu$,
$S^t_\lambda = B^t_a(S^t_\mu) = B^t_a(\varphi_t(Q_\mu)) = \varphi_t(B_a(Q_\mu)) =
\varphi_t(Q_\lambda)$, using the IH and Lemma~\ref{lem:inter}.
\end{proof}

\begin{example}
$Q_{(1)} = 2X_0 = 2p_1$ [\code{Qfun\_singleton}] and
$S^t_{(1)} = 2c_0 X_0 = 2(1-t)p_1 = (1-t)Q_{(1)} = \varphi_t(Q_{(1)})$
[\code{Sfun\_singleton}].
\end{example}

\begin{theorem}[Automorphism and inversion]\label{thm:auto}
Over $K=\QQ(t)$, $\varphi_t$ is a $K$-algebra automorphism with inverse $\psi_t$:
$\psi_t\circ\varphi_t = \id = \varphi_t\circ\psi_t$
[\code{psiT\_phiT}, \code{phiT\_psiT}, \code{phiTEquiv}]. Hence $\varphi_t$ is bijective
[\code{phiT\_injective}] and $Q_\lambda = \psi_t(S^t_\lambda)$ [\code{Qfun\_eq\_psiT\_Sfun}].
\end{theorem}
\begin{proof}
Check on generators: $\psi_t(\varphi_t(X_k)) = c_k d_k X_k = X_k$ since $c_k d_k=1$;
symmetrically. Applying $\psi_t$ to Theorem~\ref{thm:triv} gives $Q_\lambda=\psi_t(S^t_\lambda)$.
\end{proof}

\begin{theorem}[Basis triviality]\label{thm:basis}
For any $g:\iota\to\mathrm{Lists}$, $\{S^t_{g(i)}\}$ is $K$-linearly independent iff
$\{Q_{g(i)}\}$ is. [\code{linearIndependent\_Sfun\_iff}]
\end{theorem}
\begin{proof}
$S^t_{g(i)} = \varphi_t(Q_{g(i)})$ is the image under the linear automorphism $\varphi_t$
(inverse $\psi_t$); independence is preserved and reflected by an isomorphism.
\end{proof}

\section{The diagonal plethysm group}\label{sec:group}

Fix an arbitrary field $K$ and $\Gam=\mathrm{MvPolynomial}(\NN,K)$.

\begin{definition}[Diagonal plethysm]
For $a:\NN\to K$ define the $K$-algebra endomorphism $\Phi_a=\mathrm{diagHom}(a)$ by
$\Phi_a(X_k)=a_k X_k$ [\code{diagHom}, \code{diagHom\_X}]; these are the endomorphisms diagonal
in the monomial basis.
\end{definition}

\begin{proposition}[Monoid law]\label{prop:monoid}
$\Phi_1=\id$ and $\Phi_a\circ\Phi_b = \Phi_{a\cdot b}$ (pointwise product)
[\code{diagHom\_one}, \code{diagHom\_comp}]; $\{\Phi_a\}$ is a commutative monoid isomorphic to
$(K,\times)^{\NN}$.
\end{proposition}
\begin{proof}
On generators $\Phi_a(\Phi_b(X_k)) = a_k b_k X_k = \Phi_{a\cdot b}(X_k)$; both sides are
algebra maps.
\end{proof}

\begin{theorem}[Faithful parametrization]\label{thm:faithparam}
$a\mapsto\Phi_a$ is injective. [\code{diagHom\_param\_injective}]
\end{theorem}
\begin{proof}
$\Phi_a=\Phi_b$ gives $(a_k-b_k)X_k=0$; as $X_k\neq0$ in the integral domain $\Gam$, $a_k=b_k$.
\end{proof}

\begin{theorem}[Automorphisms on the unit locus]\label{thm:unitgroup}
If $a_k\neq0$ for all $k$, then $\Phi_a$ is an automorphism with inverse $\Phi_{a^{-1}}$
[\code{diagEquiv}, \code{diagHom\_injective\_of\_nonzero}]. The assignment of an invertible
sequence $a:\NN\to K^\times$ to $\Phi_a$ is an injective group homomorphism
$\mathrm{diagGroupHom}:(K^\times)^{\NN}\to\Aut_K(\Gam)$ [\code{diagGroupHom},
\code{diagGroupHom\_injective}]; the diagonal plethysm group is a faithful copy of
$(K^\times)^{\NN}$.
\end{theorem}
\begin{proof}
$\Phi_a\circ\Phi_{a^{-1}}=\Phi_{a\cdot a^{-1}}=\Phi_1=\id$ by
Proposition~\ref{prop:monoid}; the homomorphism property is the same proposition restricted to
units; injectivity is Theorem~\ref{thm:faithparam}.
\end{proof}

\begin{corollary}[$\varphi_t$ inside the group]
Over $K=\QQ(t)$, $\varphi_t=\Phi_c$ and $\psi_t=\Phi_{c^{-1}}=\Phi_d$ [\code{phiT\_eq\_diagHom}].
The inversion of Theorem~\ref{thm:auto} follows abstractly from Proposition~\ref{prop:monoid}
and $c_k d_k=1$, and $\varphi_t$ is an automorphism since $c\in(K^\times)^{\NN}$
(Lemma~\ref{lem:ccne}, Theorem~\ref{thm:unitgroup}) [\code{phiT\_injective}].
\end{corollary}

\section{The non-triviality boundary}\label{sec:boundary}

\begin{theorem}[Injectivity dichotomy]\label{thm:dich}
For any $a:\NN\to K$, $\Phi_a$ is injective iff $a_k\neq0$ for all $k$.
[\code{diagHom\_injective\_iff}]
\end{theorem}
\begin{proof}
($\Leftarrow$) Theorem~\ref{thm:unitgroup}. ($\Rightarrow$) If $a_k=0$ then
$\Phi_a(X_k)=0=\Phi_a(0)$ while $X_k\neq0$ [\code{diagHom\_not\_injective\_of\_zero}].
\end{proof}

\begin{example}[Degenerations]
A sequence vanishing at a single index $k_0$ (and $1$ elsewhere) yields a non-injective $\Phi_a$
collapsing $X_{k_0}$ [\code{diagHom\_single\_zero\_not\_injective}]; the all-zero sequence is the
total collapse [\code{diagHom\_const\_zero\_not\_injective}].
\end{example}

\begin{theorem}[Specialization $t\mapsto1$]
With $c^{(s)}_k=1-s^{2k+1}$ (so $c=c^{(t)}$) [\code{ccAt}], we have $c^{(1)}_k=0$
[\code{ccAt\_one\_eq\_zero}], and $\Phi_{c^{(1)}}$ is not injective
[\code{phiT\_specialize\_one\_not\_injective}]. Thus $\varphi_t=\Phi_{c^{(t)}}$ is an
isomorphism only away from the vanishing locus of $1-t^{2k+1}$.
\end{theorem}
\begin{proof}
$c^{(1)}_0=1-1=0$, so Theorem~\ref{thm:dich} applies at $k_0=0$.
\end{proof}

Since $c^{(0)}_k=1$ for all $k$ (so $\varphi_t$ specializes to $\Phi_1=\id$ at $t=0$), the
parameter traverses the group: identity at $t=0$, genuine automorphisms for transcendental $t$,
total collapse at $t=1$.

\section{Algorithms}

\textbf{Algorithm A} (one-row $q_m$): the Newton recursion, $O(N^2)$ for $q_0,\dots,q_N$.
\textbf{Algorithm B} (Schur $Q$ / $t$-Schur via folds): apply $B_{\lambda_i}$ (resp.\
$B^t_{\lambda_i}$) right-to-left to $1$. \textbf{Algorithm C} (trivialization): compute
$Q_\lambda$ once, then apply $\varphi_t$ by rescaling each monomial $\prod X_k^{m_k}$ by
$\prod c_k^{m_k}$ (Theorem~\ref{thm:triv}); invert by dividing (Theorem~\ref{thm:auto}).

\section{Applications and discussion}

Because $\varphi_t$ conjugates the vertex calculus ($B^t_n = \varphi_t\circ B_n\circ\varphi_t^{-1}$
by Lemma~\ref{lem:inter}), the $t$-Schur structure constants equal the Schur-$Q$ ones up to
explicit scalars $\prod(1-t^{n_i})$; the shifted-tableaux combinatorics is $t$-independent.
Algorithm~C shows the parametric family need not be regenerated per problem. Triviality is group
structure: $\varphi_t$ is one element of the faithful commutative group of diagonal plethysms.

\section{Future directions}

\begin{conjecture}[Two-parameter composition closure]
$\varphi_s\circ\varphi_t$ is a diagonal plethysm with weight $(1-s^n)(1-t^n)$, and
$S^{s,t}_\lambda=\varphi_s(\varphi_t(Q_\lambda))$ is a single-shift Schur-$Q$ image only when
$s,t$ are multiplicatively dependent. The law $\Phi_v\circ\Phi_w=\Phi_{v\cdot w}$ reduces this
to factoring $(1-s^n)(1-t^n)$ as a single $1-u^n$.
\end{conjecture}

\begin{conjecture}[Specialization $t\to0$ recovers Schur $Q$]
Under $t\mapsto0$ on the scalars $c_k$ (well defined since $c_k$ has nonzero constant term),
$S^t_\lambda$ degenerates to $Q_\lambda$, uniquely at $t=0$; here $\varphi_t\to\Phi_1=\id$ and
uniqueness uses faithfulness.
\end{conjecture}

\begin{conjecture}[Deformation-invariant Pieri / Murnaghan--Nakayama coefficients]
The $t$-Schur structure constants under $B^t_n$ equal the Schur-$Q$ constants up to
$\prod(1-t^{n_i})$; all combinatorial coefficients are unchanged. The intertwining
$B^t_n\circ\varphi_t=\varphi_t\circ B_n$ conjugates the Pieri calculus by an automorphism.
\end{conjecture}

\begin{conjecture}[Group action characterizes triviality]
A basis deformation of $\{Q_\lambda\}$ is plethystically trivial precisely when induced by a
member of the faithful diagonal plethysm group.
\end{conjecture}

\section{Formal verification}

All theorems were formally proved in Lean~4 with Mathlib, across three files:
\code{OddPowerSumPlethysm.lean} (the operator and its automorphism property),
\code{PlethysticTrivialityShiftedTSchur.lean} (the vertex construction and triviality
identities), and \code{DiagonalPlethysmGroup.lean} (the group, faithfulness, dichotomy, and
boundary). Bracketed names are the formal identifiers.

\end{document}

