    print("\n[Injectivity dichotomy]  some a_k = 0  =>  Phi_a not injective   [diagHom_injective_iff]")
    a_zero = [Fraction(1) for _ in range(kmax + 1)]
    a_zero[2] = Fraction(0)
    collapsed = diag_hom(a_zero, sf_gen(2))
